// Generated by BMSF deterministic satellite bootstrap.
import { checkManifestContract } from "@bmbos/application-contracts";
import { applicationManifest } from "./manifest";

const validation = checkManifestContract(applicationManifest);

if (!validation.ok) {
  throw new Error(
    "BMSF generated an invalid application manifest: " +
      validation.errors.map((item) => item.path + ": " + item.message).join("; "),
  );
}

export const applicationRegistration = {
  appKey: validation.manifest.identity.appKey,
  routeNamespace: validation.manifest.runtime.routeNamespace,
  manifest: validation.manifest,
};
